import{_ as t,o as i,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"CDS Pacific: Performance","description":"","frontmatter":{"title":"CDS Pacific: Performance","date":"2020-04-03T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","Pacific版本","性能优化","分布式存储","BlueStore","PG balancer","持续集成","性能测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/CDS_Pacific_-_Performance.md","filePath":"posts/2020/CDS_Pacific_-_Performance.md","lastUpdated":1780459816000}'),a={name:"posts/2020/CDS_Pacific_-_Performance.md"};function e(n,r,s,g,c,d){return i(),l("div",null,[...r[0]||(r[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次会议主要讨论了Ceph项目在即将发布的Pacific版本中的性能优化和开发进展。会议涵盖了多个关键领域，包括BlueStore性能优化、PG log和PG balancer的改进、RGW优化、MDS和CephFS的动态子树分区方案、RBD和内核客户端的性能问题，以及持续集成和性能测试的增强。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>BlueStore性能优化</strong></p><ul><li><strong>Adam&#39;s comb family sharding</strong>: 该项目旨在改善写入放大和空间放大问题，目前正在开发中。</li><li><strong>Double cache fix</strong>: 解决缓存重复数据问题，避免缓存污染。</li><li><strong>Cache age based bidding</strong>: 通过分析缓存中数据的相对年龄来优化内存分配。</li><li><strong>Node data structure diet</strong>: 减小O节点数据结构的大小，预计带来10-20%的改进。</li><li><strong>Hybrid allocator and deferring big writes</strong>: 减少硬盘上的中间层，特别是在4K块大小的情况下。</li></ul></li><li><p><strong>PG log和PG balancer的改进</strong></p><ul><li><strong>PG scaling和PG balancer的变化</strong>: 确保不会引入不良行为。</li></ul></li><li><p><strong>RGW优化</strong></p><ul><li><strong>避免写入暂停</strong>: 针对bucket index splitting的优化，优先级较低。</li></ul></li><li><p><strong>MDS和CephFS的动态子树分区方案</strong></p><ul><li><strong>MDS性能优化</strong>: 改变MDS的请求服务方式来提高性能。</li></ul></li><li><p><strong>RBD和内核客户端的性能问题</strong></p><ul><li><strong>25Gbps链路的瓶颈问题</strong>: 正在诊断中，希望在Pacific版本中解决。</li></ul></li><li><p><strong>持续集成和性能测试</strong></p><ul><li><strong>性能测试框架的增强</strong>: 通过Jenkins集成CBT来运行性能测试。</li><li><strong>长期运行的大型规模测试</strong>: 考虑使用Toothology进行更复杂的性能测试。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>BlueStore的多个性能优化将在Pacific版本中继续推进。</strong></li><li><strong>PG log和PG balancer的改进将持续进行，以确保稳定性和性能。</strong></li><li><strong>RGW的优化将根据优先级进行，可能会有所延迟。</strong></li><li><strong>MDS和CephFS的优化将尝试新的方法来提高处理大型目录的性能。</strong></li><li><strong>RBD和内核客户端的问题将作为优先事项进行诊断和修复。</strong></li><li><strong>性能测试框架将得到增强，包括Jenkins集成和Toothology的使用。</strong></li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>继续推进BlueStore的性能优化工作，特别是Adam&#39;s comb family sharding和相关缓存优化。</strong></li><li><strong>持续监控和改进PG log和PG balancer的性能和稳定性。</strong></li><li><strong>评估RGW优化的优先级，并根据资源情况进行调整。</strong></li><li><strong>探索MDS和CephFS的新优化方法，特别是在处理大型目录文件时。</strong></li><li><strong>解决RBD和内核客户端的性能瓶颈问题，特别是在高速网络环境下。</strong></li><li><strong>增强性能测试框架，确保能够有效检测和防止性能回归。</strong></li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>本次会议为Ceph的Pacific版本开发提供了明确的方向和行动计划，特别是在性能优化和持续集成测试方面。所有团队成员将继续努力，确保新版本的质量和性能达到预期目标。</p>',11)])])}const p=t(a,[["render",e]]);export{u as __pageData,p as default};
